<template><section class="shop-page"><header class="shop-heading"><div><span class="shop-eyebrow">TESTE ANTES DE CONECTAR</span><h1>Simulador de atendimento</h1><p>Converse como cliente usando o catálogo atual da sua loja.</p></div><button class="shop-secondary" :disabled="busy" @click="newConversation"><i class="ri-add-line"></i> Nova simulação</button></header><div v-if="error" class="shop-alert error" role="alert">{{error}}</div><div class="shop-chat-grid"><section class="shop-panel shop-chat"><header class="shop-chat-header"><span><i class="ri-chat-smile-2-line"></i></span><div><strong>{{shop.company?.name}}</strong><small>{{conversation?.status==='bot'||!conversation?'Assistente do catálogo':conversation.department_name+' · Equipe da loja'}}</small></div><span class="shop-status OUT_OF_STOCK">Simulação local</span></header><div ref="messageList" class="shop-chat-messages"><div v-if="!conversation" class="shop-bubble assistant">Olá! Qual produto você procura? Informe o nome ou código para eu consultar o catálogo da loja.</div><div v-for="item in conversation?.messages||[]" :key="item.id" class="shop-bubble" :class="item.role"><small>{{item.role==='customer'?'Cliente':item.role==='assistant'?'Assistente':item.department_name+' · Equipe'}}</small>{{item.text}}</div><div v-if="conversation&&conversation.status!=='bot'" class="shop-chat-system">Esta conversa foi encaminhada para {{conversation.department_name}}. O assistente automático está pausado.</div><div v-if="busy" class="shop-chat-system">Enviando…</div></div><form class="shop-chat-compose" @submit.prevent="send"><input v-model="message" aria-label="Mensagem do cliente" maxlength="1000" required placeholder="Ex.: Qual o preço do arroz?"/><button class="shop-primary" :disabled="busy||!message.trim()" aria-label="Enviar mensagem"><i class="ri-send-plane-2-line"></i></button></form></section><aside class="shop-chat-notes"><span class="shop-status AVAILABLE">Sem custo de API</span><h2>O catálogo é a fonte.</h2><p>Este teste faz uma busca por palavras. Ainda não utiliza LLM nem envia mensagens pelo WhatsApp.</p><h3>Experimente perguntar</h3><button v-for="text in suggestions" :key="text" @click="message=text">{{text}}<i class="ri-arrow-right-up-line"></i></button><div class="shop-form-note">A disponibilidade é informada pelo comerciante. O assistente não acompanha vendas ou quantidades automaticamente.</div><RouterLink v-if="conversation" :to="{path:'/conversas',query:{conversa:conversation.id}}" class="shop-primary" style="margin-top:20px">Abrir na equipe <i class="ri-arrow-right-line"></i></RouterLink><p v-if="conversation" class="shop-muted">Use a tela de conversas para transferir entre Balcão, Açougue e Caixa e responder como equipe.</p></aside></div></section></template>
<script setup>
import { computed,nextTick,onBeforeUnmount,onMounted,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { useShopStore } from '@/stores/shop.store'
import { shopApi } from '@/api/shop.api'
import { apiError } from '@/utils/shop'
const shop=useShopStore(),route=useRoute(),router=useRouter(),conversation=ref(null),message=ref(''),busy=ref(false),error=ref(''),messageList=ref(null)
const suggestions=computed(()=>shop.products.slice(0,3).map(p=>'Qual o preço de '+p.name+'?'))
let disposed=false,timer=null,request=0
async function scroll(){await nextTick();if(messageList.value)messageList.value.scrollTop=messageList.value.scrollHeight}
async function refresh(){const id=String(route.query.conversa||''),n=++request;if(!id||busy.value)return;try{const {data}=await shopApi.conversation(id);if(disposed||n!==request||route.query.conversa!==id)return;const changed=conversation.value?.version!==data.conversation.version;conversation.value=data.conversation;if(changed)scroll()}catch(e){if(!disposed&&n===request)error.value=apiError(e)}}
async function newConversation(){request++;conversation.value=null;message.value='';error.value='';await router.replace('/simulador')}
async function send(){if(busy.value||!message.value.trim())return;error.value='';busy.value=true;request++;try{const {data}=await shopApi.chat({message:message.value,...(conversation.value?{conversation_id:conversation.value.id}:{})});if(disposed)return;conversation.value=data.conversation;message.value='';await router.replace({path:'/simulador',query:{conversa:data.conversation.id}});await shop.load();scroll()}catch(e){error.value=apiError(e)}finally{busy.value=false}}
watch(()=>route.query.conversa,()=>{if(route.query.conversa!==conversation.value?.id){conversation.value=null;refresh()}})
onMounted(()=>{refresh();timer=setInterval(()=>{if(document.visibilityState==='visible')refresh()},4000)})
onBeforeUnmount(()=>{disposed=true;request++;clearInterval(timer)})
</script>
